<template><section class="routines-page"><div v-if="loadError" class="bio-nexus-message bio-nexus-message-error"><strong>No fue posible cargar las rutinas.</strong><span>{{loadError}}</span></div><section class="bio-nexus-administrative-directory"><div v-if="loading" class="bio-nexus-empty-state">Cargando rutinas...</div><div v-else-if="!rows.length" class="bio-nexus-empty-state">No existen rutinas registradas.</div><BioNexusDataGrid v-else class="routines-grid" :row-data="rows" :column-defs="columnDefs" :default-col-def="defaultColDef" :components="gridComponents" :get-row-id="getRowId" :quick-filter-text="searchText" :search-enabled="true" v-model:search-model-value="searchText" search-placeholder="Buscar rutina" :refresh-enabled="true" :refreshing="loading" :refresh-disabled="saving" :page-size="10" :page-size-selector="[10,20,50,100]" :min-grid-height="300" :max-grid-height="560" @refresh="loadRows" @row-context-menu="openContextMenu"><template #actions><BioNexusActionButton v-if="canCreate" icon="create" icon-only shape="rounded" size="md" variant="primary" label="Nueva rutina" :disabled="loading||saving" @click="formDialog?.openCreate()" /></template></BioNexusDataGrid><BioNexusContextMenu ref="contextMenu" :open="contextState.open" :x="contextState.x" :y="contextState.y" :items="contextItems" @close="closeContextMenu" @select="runContextAction"/></section><RoutineDialog ref="formDialog" :saving="saving" :can-create="canCreate" :can-update="canUpdate" :exams="exams" @submit="saveForm"/><BioNexusConfirmDialog ref="deleteDialog" /></section></template>
<script setup>
import{computed,nextTick,onMounted,ref}from"vue";import BioNexusDataGrid from"@/components/grid/BioNexusDataGrid.vue";import BioNexusGridActionsCell from"@/components/grid/BioNexusGridActionsCell.vue";import BioNexusActionButton from"@/components/ui/BioNexusActionButton.vue";import BioNexusConfirmDialog from"@/components/ui/BioNexusConfirmDialog.vue";import BioNexusContextMenu from"@/components/ui/BioNexusContextMenu.vue";import BioNexusDialog from"@/components/ui/BioNexusDialog.vue";import RoutineDialog from"@/components/routines/RoutineDialog.vue";import{getExamGroups,getExamsByGroup}from"@/services/examCatalogService";import{createRoutine,deleteRoutine,getRoutines,routineError,updateRoutine}from"@/services/routinesService";import{useAuthorizationStore}from"@/stores/authorization";import{useBioNexusToast}from"@/composables/useBioNexusToast";
const authorization=useAuthorizationStore(),toast=useBioNexusToast(),rows=ref([]),exams=ref([]),loading=ref(false),saving=ref(false),loadError=ref(""),searchText=ref(""),formDialog=ref(null),deleteDialog=ref(null),deleteTarget=ref(null),contextMenu=ref(null),contextState=ref({open:false,x:0,y:0,row:null});const canCreate=computed(()=>authorization.hasPermission("routines.create")),canUpdate=computed(()=>authorization.hasPermission("routines.update")),canDelete=computed(()=>authorization.hasPermission("routines.delete"));const defaultColDef=Object.freeze({sortable:true,filter:true,resizable:true,suppressHeaderMenuButton:true}),gridComponents=Object.freeze({BioNexusGridActionsCell});const columnDefs=computed(()=>[{field:"description",headerName:"Descripción",minWidth:260,flex:1},{field:"details",headerName:"Detalles",minWidth:280,flex:1.2},{field:"examCount",headerName:"Exámenes",width:130,cellClass:"routines-center",headerClass:"routines-center-header"},{colId:"actions",headerName:"Acciones",width:110,sortable:false,filter:false,resizable:false,headerClass:"bio-nexus-grid-actions-header",cellClass:"bio-nexus-grid-actions-cell",cellRenderer:"BioNexusGridActionsCell",cellRendererParams:{actions:[{key:"edit",label:"Editar",icon:"edit",visible:()=>canUpdate.value,disabled:()=>saving.value,onClick:row=>formDialog.value?.openEdit(row)},{key:"delete",label:"Eliminar",icon:"delete",variant:"danger",visible:()=>canDelete.value,disabled:()=>saving.value,onClick:openDelete}]}}]);const contextItems=computed(()=>{const row=contextState.value.row;return row?[{key:"edit",label:"Editar",icon:"edit",visible:canUpdate.value,action:()=>formDialog.value?.openEdit(row)},{key:"delete",label:"Eliminar",icon:"delete",variant:"danger",visible:canDelete.value,disabled:saving.value,action:()=>openDelete(row)}]:[]});
function getRowId({data}){return String(data.id)}async function loadRows(){if(loading.value||saving.value)return;loading.value=true;loadError.value="";try{const[loaded,groups]=await Promise.all([getRoutines(),getExamGroups()]);rows.value=loaded;exams.value=(await Promise.all(groups.map(group=>getExamsByGroup(group.id)))).flat().sort((a,b)=>a.description.localeCompare(b.description))}catch(error){rows.value=[];loadError.value=routineError(error,"No fue posible consultar las rutinas.");toast.error(loadError.value)}finally{loading.value=false}}function replaceRow(saved){const next=rows.value.map(row=>row.id===saved.id?saved:row);if(!next.some(row=>row.id===saved.id))next.push(saved);rows.value=next.sort((a,b)=>a.description.localeCompare(b.description))}async function saveForm(payload){if(saving.value)return;saving.value=true;formDialog.value?.clearError();try{const saved=payload.mode==="create"?await createRoutine(payload.values):await updateRoutine(payload.record.id,payload.values);replaceRow(saved);formDialog.value?.close();toast.success(payload.mode==="create"?"Rutina creada correctamente.":"Rutina actualizada correctamente.")}catch(error){formDialog.value?.setError(routineError(error,"No fue posible guardar la rutina."))}finally{saving.value=false}}async function openDelete(row){const confirmed=await deleteDialog.value?.ask({kicker:"Confirmación",title:"Eliminar rutina",message:`Se eliminará ${row.description} y sus relaciones.`,icon:"delete",variant:"danger",confirmIcon:"delete",confirmText:"Sí, eliminar rutina",cancelText:"Cancelar"});if(!confirmed)return;deleteTarget.value=row;await confirmDelete()}async function confirmDelete(){if(!deleteTarget.value||saving.value)return;saving.value=true;try{await deleteRoutine(deleteTarget.value.id);rows.value=rows.value.filter(row=>row.id!==deleteTarget.value.id);deleteTarget.value=null;toast.success("Rutina eliminada correctamente.")}catch(error){toast.error(routineError(error,"No fue posible eliminar la rutina."))}finally{saving.value=false}}async function openContextMenu({event,row}){if(!canUpdate.value&&!canDelete.value)return;event.preventDefault();contextState.value={open:true,x:event.clientX,y:event.clientY,row};await nextTick();contextMenu.value?.positionMenu?.()}function closeContextMenu(){contextState.value={open:false,x:0,y:0,row:null}}async function runContextAction(item){const action=item?.action;closeContextMenu();if(typeof action==="function")await action()}onMounted(loadRows);
</script>
